        let y = b.next();
        let xs = format!("{:?}", x);
        let ys = format!("{:?}", y);
        if xs != ys { panic!("mismatch on {:?}: old {} new {}", line, xs, ys); }
        if x.is_none() || matches!(x, Some(Err(_))) { extra += 1; if extra > 3 { break; } }
    }
}

fn count<'a, I: Iterator<Item = Result<T, E>>, T, E>(it: I) -> u64 {
    let mut n = 0u64;
    for t in it { match t { Ok(t) => { black_box(&t); n += 1 } Err(_) => { n += 1000; break } } }
    n
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_default();
    if mode == "exhaustive" {
        let alphabet = [" ", "\t", "[", "]", "\"", "\\", "=", "a", "n", "é"];
        let maxlen = 7;
        let mut total = 0u64;
        let mut idx = vec![0usize; 0];
        for len in 0..=maxlen {
            idx.clear(); idx.resize(len, 0);
            loop {
                let s: String = idx.iter().map(|&i| alphabet[i]).collect();
                same(&s); total += 1;
                let mut k = 0;
                while k < len { idx[k] += 1; if idx[k] < alphabet.len() { break; } idx[k] = 0; k += 1; }
                if k == len { break; }
            }
        }
        println!("exhaustive ok: {total} lines");
        return;
    }
    // random longer lines from token fragments
    let frags = ["[2024-05-01T12:00:00Z]", " ", "\t", "level=info", "msg=\"disk 91% full\"", "x=", "\"", "\\", "=",
                 "[", "]", "word", "a=\"q\\\"b\\n\"", "k=v=w", "é", "\\x", "u=\"", "\"\"", "=\"\""];
    let mut seed = 0x1234_5678_9abc_def0u64;
    let mut rnd = || { seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17; seed };
    for _ in 0..3_000_000 {
        let n = (rnd() % 12) as usize;
        let s: String = (0..n).map(|_| frags[(rnd() % frags.len() as u64) as usize]).collect();
        same(&s);
    }
    println!("random ok");
    // benchmark: realistic lines, ~1/50 malformed
    let mut lines = Vec::new();
    for i in 0..400_000u64 {
        let mut s = format!("[2024-05-01T12:{:02}:{:02}Z] level=info service=api-{} msg=\"request \\\"GET /v1/items/{}\\\" done in {}ms\" user=u{} retries= status=200 ok", i%60, i%60, i%7, i, i%900, i%1000);
        if i % 50 == 0 { s.push_str(" bad\"quote"); }
        lines.push(s);
    }
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    for round in 0..3 {
        for (name, which) in [("old", 0), ("new", 1)] {
            let t = Instant::now();
            let mut sum = 0u64;
            for _ in 0..10 { for l in &lines {
                sum += if which == 0 { count(old::tokenize(black_box(l))) } else { count(new::tokenize(black_box(l))) };
            }}
            let dt = t.elapsed().as_secs_f64();
            println!("round {round} {name}: {:.3}s  {:.0} MB/s  (sum {sum})", dt, (bytes*10) as f64 / dt / 1e6);
        }
    }
}
