        let mut total = 0u64;
        for len in 0..=7usize {
            let mut idx = vec![0usize; len];
            loop {
                let s: String = idx.iter().map(|&i| alphabet[i]).collect();
                same(&s); total += 1;
                let mut k = 0;
                while k < len { idx[k] += 1; if idx[k] < alphabet.len() { break; } idx[k] = 0; k += 1; }
                if k == len { break; }
            }
        }
        println!("exhaustive ok: {total} lines");
        return;
    }
    let mut lines = Vec::new();
    for i in 0..400_000u64 {
        let mut s = format!(r#"[2024-05-01T12:{:02}:{:02}Z] level=info service=api-{} msg="request \"GET /v1/items/{}\" done in {}ms" user=u{} retries= status=200 ok"#, i % 60, i % 60, i % 7, i, i % 900, i % 1000);
        if i % 50 == 0 { s.push_str(" bad\"quote"); }
        lines.push(s);
    }
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    let mut best = [f64::MAX; 2];
    let mut sums = [0u64; 2];
    for _ in 0..15 {
        for which in [0usize, 1] {
            let t = Instant::now();
            let mut sum = 0u64;
            for _ in 0..10 { for l in &lines {
                sum += if which == 0 { count(old::tokenize(black_box(l))) } else { count(new::tokenize(black_box(l))) };
            }}
            best[which] = best[which].min(t.elapsed().as_secs_f64());
            sums[which] = sum;
