    loop {
        let x = a.next();
        let y = b.next();
        let xs = format!("{:?}", x);
        let ys = format!("{:?}", y);
        if xs != ys { panic!("mismatch on {:?}: old {} new {}", line, xs, ys); }
        if x.is_none() || matches!(x, Some(Err(_))) { extra += 1; if extra > 3 { break; } }
    }


