        let maxlen = 7;
        let mut total = 0u64;
        let mut idx = vec![0usize; 0];
        for len in 0..=maxlen {
            idx.clear(); idx.resize(len, 0);
            loop {
                let s: String = idx.iter().map(|&i| alphabet[i]).collect();
                same(&s); total += 1;
                let mut k = 0;
                while k < len { idx[k] += 1; if idx[k] < alphabet.len() { break; } idx[k] = 0; k += 1; }
                if k == len { break; }
            }
        }
        println!("exhaustive ok: {total} lines");
        return;
    }
    // random longer lines from token fragments
    let frags = ["[2024-05-01T12:00:00Z]", " ", "\t", "level=info", "msg=\"disk 91% full\"", "x=", "\"", "\\", "=",
                 "[", "]", "word", r#"a="q\"b\n""#, "k=v=w", "é", r"\x", r"\\", r#"\""#, "\\n", "u=\"", "\"\"", "=\"\""];
    let mut seed = 0x1234_5678_9abc_def0u64;
    let mut rnd = || { seed ^= seed << 13; seed ^= seed >> 7; seed ^= seed << 17; seed };
    for _ in 0..3_000_000 {
        let n = (rnd() % 12) as usize;
        let s: String = (0..n).map(|_| frags[(rnd() % frags.len() as u64) as usize]).collect();
        same(&s);
    }
