    let mut lines = Vec::new();
    for i in 0..400_000u64 {
        let mut s = format!("[2024-05-01T12:{:02}:{:02}Z] level=info service=api-{} msg=\"request \\\"GET /v1/items/{}\\\" done in {}ms\" user=u{} retries= status=200 ok", i%60, i%60, i%7, i, i%900, i%1000);
        if i % 50 == 0 { s.push_str(" bad\"quote"); }
        lines.push(s);
    }
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    let mut best = [f64::MAX; 2];
    for round in 0..15 {
        for (name, which) in [("old", 0usize), ("new", 1usize)] {
            let t = Instant::now();
            let mut sum = 0u64;
            for _ in 0..10 { for l in &lines {
                sum += if which == 0 { count(old::tokenize(black_box(l))) } else { count(new::tokenize(black_box(l))) };
            }}
            let dt = t.elapsed().as_secs_f64(); best[which] = best[which].min(dt); let _ = round;
            let _ = (name, sum);
        }
    }

